64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    private final OwnerFieldsValidator ownerFieldsValidator;
80	
81	    private final PostcodeValidator postcodeValidator;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final EmailNormalizer emailNormalizer;
86	
87	    private final AddressNormalizer addressNormalizer;
88	
89	    private final BusinessDayResolver businessDayResolver;
90	
91	    private final OwnerAuditLogger ownerAuditLogger;
92	
93	    private final HouseholdIdGenerator householdIdGenerator;
94	
95	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
96	
97	    /** Maximum number of owners a single city may hold before further creations are rejected. */
98	    static final long MAX_OWNERS_PER_CITY = 50;
99	
100	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
101	    static final long MAX_OWNERS_PER_DAY = 100;
102	
103	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
104	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper,
110	                                 OwnerFieldsValidator ownerFieldsValidator,
111	                                 PostcodeValidator postcodeValidator,
112	                                 TelephoneNormalizer telephoneNormalizer,
113	                                 EmailNormalizer emailNormalizer,
114	                                 AddressNormalizer addressNormalizer,
115	                                 BusinessDayResolver businessDayResolver,
116	                                 OwnerAuditLogger ownerAuditLogger,
117	                                 HouseholdIdGenerator householdIdGenerator,
118	                                 IdempotencyKeyRegistry idempotencyKeyRegistry) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	        this.ownerFieldsValidator = ownerFieldsValidator;
124	        this.postcodeValidator = postcodeValidator;
125	        this.telephoneNormalizer = telephoneNormalizer;
126	        this.emailNormalizer = emailNormalizer;
127	        this.addressNormalizer = addressNormalizer;
128	        this.businessDayResolver = businessDayResolver;
129	        this.ownerAuditLogger = ownerAuditLogger;
130	        this.householdIdGenerator = householdIdGenerator;
131	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
137	        Collection<Owner> owners;
138	        if (lastName != null) {
139	            owners = this.clinicService.findOwnerByLastName(lastName);
140	        } else {
141	            owners = this.clinicService.findAllOwners();
142	        }
143	        if (owners.isEmpty()) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
152	        Owner owner = this.clinicService.findOwnerById(ownerId);
153	        if (owner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
162	        Integer existingOwnerId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
163	        if (existingOwnerId != null) {
164	            Owner existingOwner = this.clinicService.findOwnerById(existingOwnerId);
165	            if (existingOwner != null) {
166	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
167	            }
168	        }
169	        this.normalizeAddress(ownerFieldsDto);
170	        this.ownerFieldsValidator.validate(ownerFieldsDto);
171	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
172	        HttpHeaders headers = new HttpHeaders();
173	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
174	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
175	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
176	        LocalDate serverDate = LocalDate.now();
177	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
178	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
179	        }
180	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
181	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
182	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
183	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
184	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
185	        }
186	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
187	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
188	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
189	        }
190	        if (owner.getPostcode() != null) {
191	            owner.setHouseholdId(this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
192	        }
193	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
194	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
195	        }
196	        Owner householdDuplicate = this.clinicService.findHouseholdDuplicateOf(owner);
197	        if (householdDuplicate != null && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
198	            throw new DuplicateHouseholdException(owner.getHouseholdId());
199	        }
200	        this.clinicService.saveOwner(owner);
201	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
202	        this.ownerAuditLogger.logCreated(owner);
203	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
204	        headers.setLocation(UriComponentsBuilder.newInstance()
205	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
206	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    /**
210	     * Canonicalize the request's address fields in place, preferring the structured form. When a
211	     * non-blank {@code addressLine1} is supplied it and the optional {@code addressLine2} are
212	     * normalized and the composed value stored on {@code address}; otherwise only the flat
213	     * {@code address} is normalized. This keeps the stored {@code address} the single canonical
214	     * value everything downstream reads.
215	     */
216	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
217	        if (ownerFieldsDto.getAddressLine1() != null && !ownerFieldsDto.getAddressLine1().isBlank()) {
218	            ownerFieldsDto.setAddressLine1(this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
219	            String line2 = this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
220	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
221	            ownerFieldsDto.setAddress(
222	                this.addressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
223	        }
224	        else {
225	            ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
226	        }
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        currentOwner.setAddress(ownerFieldsDto.getAddress());
237	        currentOwner.setCity(ownerFieldsDto.getCity());
238	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
239	        currentOwner.setLastName(ownerFieldsDto.getLastName());
240	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
241	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
242	        this.clinicService.saveOwner(currentOwner);
243	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
244	    }
245	
246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Transactional
248	    @Override
249	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
250	        Owner owner = this.clinicService.findOwnerById(ownerId);
251	        if (owner == null) {
252	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	        }
254	        this.clinicService.deleteOwner(owner);
255	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
256	    }
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner == null) {
263	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	        }
265	        HttpHeaders headers = new HttpHeaders();
266	        Pet pet = petMapper.toPet(petFieldsDto);
267	        owner.setId(ownerId);
268	        pet.setOwner(owner);
269	        pet.getType().setName(null);
270	        this.clinicService.savePet(pet);
271	        PetDto petDto = petMapper.toPetDto(pet);
272	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
273	            .buildAndExpand(pet.getId()).toUri());
274	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Override
279	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
280	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
281	        if (currentOwner != null) {
282	            Pet currentPet = this.clinicService.findPetById(petId);
283	            if (currentPet != null) {
284	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
285	                currentPet.setName(petFieldsDto.getName());
286	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
287	                this.clinicService.savePet(currentPet);
288	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
289	            }
290	        }
291	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
292	    }
293	
294	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
295	    @Override
296	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
297	        HttpHeaders headers = new HttpHeaders();
298	        Visit visit = visitMapper.toVisit(visitFieldsDto);
299	        Pet pet = new Pet();
300	        pet.setId(petId);
301	        visit.setPet(pet);
302	        this.clinicService.saveVisit(visit);
303	        VisitDto visitDto = visitMapper.toVisitDto(visit);
304	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
305	            .buildAndExpand(visit.getId()).toUri());
306	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
307	    }
308	
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
313	        Owner owner = this.clinicService.findOwnerById(ownerId);
314	        if (owner != null) {
315	            Pet pet = owner.getPet(petId);
316	            if (pet != null) {
317	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
318	            }
319	        }
320	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
321	    }
322	}
