19	import org.springframework.samples.petclinic.model.E164CountryCode;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Normalizes an owner's telephone number into E.164 form on create.
24	 *
25	 * <p>Spaces, dashes and brackets are stripped. A leading {@code +} and its country code
26	 * are kept as-is; without one, the default country code {@code +61} is assumed and a
27	 * single leading {@code 0} is dropped from the national digits. The result must carry
28	 * between 8 and 15 digits after the {@code +}, and for a {@linkplain E164CountryCode
29	 * recognized country code} the national number must have exactly the length that country
30	 * requires (e.g. {@code +61} needs 9 national digits, {@code +1} needs 10). This E.164
31	 * string is what gets stored, returned, and compared when detecting duplicate telephones.
32	 */
33	@Component
34	public class TelephoneNormalizer {
35	
36	    private static final String DEFAULT_COUNTRY_CODE = "61";
37	
38	    private static final int MIN_DIGITS = 8;
39	
40	    private static final int MAX_DIGITS = 15;
41	
42	    /**
43	     * Converts {@code raw} into its E.164 representation.
44	     *
45	     * @param raw the submitted telephone value
46	     * @return the normalized E.164 telephone number (a leading {@code +} followed by digits)
47	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
48	     */
49	    public String normalize(String raw) {
50	        String trimmed = raw == null ? "" : raw.strip();
51	        boolean explicitCountryCode = trimmed.startsWith("+");
52	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
53	
54	        String digits;
55	        if (explicitCountryCode) {
56	            digits = stripped.substring(1);
57	        } else {
58	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
59	            digits = DEFAULT_COUNTRY_CODE + national;
60	        }
61	
62	        if (!digits.matches("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
63	            throw new InvalidTelephoneException(raw);
64	        }
65	        E164CountryCode.forE164Digits(digits).ifPresent(country -> {
66	            String national = digits.substring(country.callingCode().length());
67	            if (!country.acceptsNationalNumber(national)) {
68	                throw new InvalidTelephoneException(raw);
69	            }
70	        });
71	        return "+" + digits;
72	    }
73	}
