18	
19	import java.util.Locale;
20	import java.util.regex.Pattern;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalizes an owner's optional email address on create/update.
26	 *
27	 * <p>The email is optional: a {@code null} or blank value is treated as absent and left
28	 * unset. When a value is present it must be a syntactically valid address whose domain is
29	 * not on the disposable-domain blocklist; it is then stored and returned lower-cased.
30	 */
31	@Component
32	public class EmailNormalizer {
33	
34	    /**
35	     * A pragmatic syntactic check: a non-empty local part, a single {@code @}, and a
36	     * domain containing at least one dot, none of the segments holding whitespace.
37	     */
38	    private static final Pattern EMAIL_PATTERN =
39	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
40	
41	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
42	
43	    public EmailNormalizer(DisposableEmailDomainValidator disposableEmailDomainValidator) {
44	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
45	    }
46	
47	    /**
48	     * Normalizes an optional email address.
49	     *
50	     * @param raw the submitted email value, possibly {@code null} or blank
51	     * @return the lower-cased email, or {@code null} when no value was supplied
52	     * @throws InvalidEmailException if a value is present but not a valid address
53	     * @throws DisposableEmailDomainException if the domain is on the disposable-domain blocklist
54	     */
55	    public String normalize(String raw) {
56	        if (raw == null || raw.isBlank()) {
57	            return null;
58	        }
59	        String trimmed = raw.trim();
60	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
61	            throw new InvalidEmailException(raw);
62	        }
63	        String normalized = trimmed.toLowerCase(Locale.ROOT);
64	        this.disposableEmailDomainValidator.validate(normalized);
65	        return normalized;
66	    }
67	}
