241	    @Override
242	    @Transactional
243	    public void saveOwner(Owner owner) throws DataAccessException {
244	        if (owner.isNew() && owner.getCustomerCode() == null) {
245	            String region = LocalityResolver.regionFor(owner.getPostcode(), owner.getCity());
246	            String customerCode =
247	                customerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName());
248	            owner.setCustomerCode(deduplicateCustomerCode(customerCode));
249	        }
250	        if (owner.isNew() && owner.getNamesakeCount() == null) {
251	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
252	        }
253	        if (owner.isNew() && owner.getMembershipNumber() == null) {
254	            owner.setMembershipNumber(
255	                membershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
256	        }
257	        if (owner.isNew() && owner.getHouseholdSize() == null) {
258	            owner.setHouseholdSize(countHouseholdMembers(owner));
259	        }
260	        ownerRepository.save(owner);
261	    }
