51	/**
52	 * Global Exception handler for REST controllers.
53	 * <p>
54	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
55	 *
56	 * @author Vitaliy Fedoriv
57	 * @author Alexander Dudkin
58	 */
59	@ControllerAdvice
60	public class ExceptionControllerAdvice {
61	
62	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
63	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
64	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
65	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
66	
67	    /**
68	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
69	     * class.
70	     *
71	     * @param e     Object referring to the thrown exception.
72	     * @param status HTTP response status.
73	     * @param url URL request.
74	     */
75	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
76	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
77	        problemDetail.setType(URI.create(url.toString()));
78	        problemDetail.setTitle(e.getClass().getSimpleName());
79	        problemDetail.setDetail(detail);
80	        problemDetail.setProperty("timestamp", Instant.now());
81	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
82	        return problemDetail;
83	    }
84	
85	    /**
86	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
87	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
88	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
89	     * would catch it and report an authorization failure as a 500.
90	     *
91	     * @param e The {@link AccessDeniedException} to propagate
92	     * @throws AccessDeniedException always
93	     */
94	    @ExceptionHandler(AccessDeniedException.class)
95	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
96	        throw e;
97	    }
98	
99	    /**
100	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
101	     *
102	     * @param e The {@link Exception} to be handled
103	     * @param request {@link HttpServletRequest} object referring to the current request.
104	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
105	     */
106	    @ExceptionHandler(Exception.class)
107	    @ResponseBody
108	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
109	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
110	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
111	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
112	        return ResponseEntity.status(status).body(detail);
113	    }
114	
115	    /**
116	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
117	     * method returns a 404 Not Found status if an entity does not exist.
118	     *
119	     * @param e The {@link DataIntegrityViolationException} to be handled
120	     * @param request {@link HttpServletRequest} object referring to the current request.
121	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
122	     */
123	    @ExceptionHandler(DataIntegrityViolationException.class)
124	    @ResponseBody
125	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
126	        logger.warn("Data integrity violation at {} {}: {}",
127	            request.getMethod(),
128	            request.getRequestURI(),
129	            e.getMessage());
130	        logger.debug("Data integrity violation stacktrace", e);
131	        HttpStatus status = HttpStatus.NOT_FOUND;
132	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
133	        return ResponseEntity.status(status).body(detail);
134	    }
135	
136	    /**
137	     * Handles exception thrown by Bean Validation on controller methods parameters
138	     *
139	     * @param e The {@link MethodArgumentNotValidException} to be handled
140	     * @param request {@link HttpServletRequest} object referring to the current request.
141	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
142	     */
143	    @ExceptionHandler(MethodArgumentNotValidException.class)
144	    @ResponseBody
145	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
146	        HttpStatus status = HttpStatus.BAD_REQUEST;
147	        BindingErrorsResponse errors = new BindingErrorsResponse();
148	        BindingResult bindingResult = e.getBindingResult();
149	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
150	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
151	            .map(FieldError::getField)
152	            .distinct()
153	            .toList());
154	        if (bindingResult.hasErrors()) {
155	            errors.addAllErrors(bindingResult);
156	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
157	                .map(fieldError -> {
158	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
159	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
160	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
161	                        fieldError.getField(),
162	                        defaultMessage,
163	                        rejectedValue);
164	                    return new ValidationMessageDto(message)
165	                        .putAdditionalProperty("field", fieldError.getField())
166	                        .putAdditionalProperty("rejectedValue", rejectedValue)
167	                        .putAdditionalProperty("defaultMessage", defaultMessage);
168	                })
169	                .toList();
170	            logger.debug("Validation error at {} {}: {}",
171	                request.getMethod(),
172	                request.getRequestURI(),
173	                bindingResult.getFieldErrors());
174	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
175	            return ResponseEntity.status(status).body(detail);
176	        }
177	        return ResponseEntity.status(status).body(detail);
178	    }
