344	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
345	     */
346	    @ExceptionHandler(FutureRegistrationDateException.class)
347	    @ResponseBody
348	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
349	        HttpStatus status = HttpStatus.BAD_REQUEST;
350	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
351	        detail.setProperty("errors", List.of("registrationDate"));
352	        return ResponseEntity.status(status).body(detail);
353	    }
354	
355	    @ExceptionHandler(OwnerDailyRegistrationLimitExceededException.class)
356	    @ResponseBody
357	    public ResponseEntity<ProblemDetail> handleOwnerDailyRegistrationLimitExceededException(OwnerDailyRegistrationLimitExceededException e, HttpServletRequest request) {
358	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
359	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
360	        detail.setProperty("errors", List.of("registrationDate"));
361	        return ResponseEntity.status(status).body(detail);
362	    }
363	
364	}
